using System.Collections.Generic;
using NaughtyAttributes;
using UnityEngine;
using UnityEngine.Serialization;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "ForgeAction", menuName = "Data/Battle/Battle Actions/Tactical Actions/Forge Action")]
public class ForgeAction : ChooseDiceAction
{
	[Header("Action Specifics")]
	[SerializeField]
	private BattleAction actionToTransmute;

	[SerializeField]
	private bool removeEmpower;

	[SerializeField]
	[FormerlySerializedAs("removeEmpower")]
	private bool removeActionValueModifier;

	[SerializeField]
	private PlayerDiceInventoryData allDicePool;

	[SerializeField]
	private bool enableExtraBattleAction;

	[SerializeField]
	[ShowIf("enableExtraBattleAction")]
	private BattleAction extraBattleAction;

	[SerializeField]
	[ShowIf("enableExtraBattleAction")]
	private int extraActionValue;

	[SerializeField]
	[ShowIf("enableExtraBattleAction")]
	private OmenLogic extraOmenLogic;

	[SerializeField]
	[ShowIf("enableExtraBattleAction")]
	private bool usedFixedActionValueUseAmountOnSecondAction;

	[SerializeField]
	[ShowIf("usedFixedActionValueUseAmountOnSecondAction")]
	private int fixedActionValueUseAmountOnSecondAction;

	public BattleAction ActionToTransmute => actionToTransmute;

	public bool EnableExtraBattleAction => enableExtraBattleAction;

	public BattleAction ExtraBattleAction => extraBattleAction;

	public int ExtraActionValue => extraActionValue;

	public override bool CheckConditionToBeCasted(bool playerHand, DiceOwnerEnum diceOwnerEnum)
	{
		if (playerHand)
		{
			return ReferenceSingleton<PlayerDiceHandHolder>.Instance.GetDiceInHandAmountForgeable() > 1;
		}
		return ReferenceSingleton<PlayerDiceHandHolder>.Instance.GetDiceInHandAmountForgeable() > 0;
	}

	public override bool CheckCondition(DiceInstance diceInstance)
	{
		return !diceInstance.ActionFace.BattleAction.NonForgeable;
	}

	public override void CastAmount(int amount, GameObject source)
	{
		ReferenceSingleton<GameStateManager>.Instance.TryEnterNoInteractionState();
		if (enableExtraBattleAction)
		{
			extraOmenLogic.ActivateOmen(extraBattleAction, extraActionValue, null, source);
		}
		for (int i = 0; i < diceList.Count; i++)
		{
			DiceInstance diceInstance = diceList[i];
			Dice dice = diceInstance.OriginalDice.InstantiateScriptableObjectTryingToCopyDiceFacesModded();
			ChangeDieFace(diceInstance.ActionFace);
			ChangeDieFace(dice.GetDiceFaces()[diceInstance.RolledDiceFaceIndex]);
			allDicePool.DiceForged(diceInstance, dice);
			if (removeActionValueModifier)
			{
				diceInstance.ActionFace.ResetActionValueModifiers();
			}
			else
			{
				List<BattleActionInteractionEnum> battleActionInteractionEnums = diceInstance.ActionFace.BattleAction.BaseBattleActionData.BattleActionInteractionEnums;
				_ = diceInstance.ActionFace.BattleAction.BaseBattleActionData;
				if (battleActionInteractionEnums.Count > 0)
				{
					diceInstance.ActionFace.UnlockActionModifiers();
					diceInstance.UpdateActionValueModifier();
				}
			}
			diceInstance.UpdateDiceFace();
			if (IsVFXEnabled())
			{
				PlaySFX();
				GetVFX(4f).GetComponent<ParticleFollower>().Initialize(diceInstance);
			}
			if (i == diceList.Count - 1)
			{
				diceInstance.GoBackToOriginalPositionAnimation(returningToHandAfterDrag: false, delegate
				{
					ReferenceSingleton<GameStateManager>.Instance.TryEnterChooseActionState(WaitForFramesType.NoFrame);
				});
			}
			else
			{
				diceInstance.GoBackToOriginalPositionAnimation();
			}
		}
		ReferenceSingleton<PlayerDiceHandPositioningAnimationManager>.Instance.UpdateDiceInHandPosition();
		void ChangeDieFace(ActionFace actionFace)
		{
			actionFace.BattleAction = actionToTransmute;
			actionFace.NewBattleAction = actionToTransmute;
			actionFace.ActionValue = amount;
			actionFace.NewActionValue = amount;
			actionFace.EnableSecondAction = false;
			actionFace.SecondBattleAction = null;
			actionFace.SecondActionValue = 0;
			actionFace.KeepChanges = true;
		}
	}
}
